    "category": "capacity_saturation",
    "service": "ingest",
    "summary": "Ingest exhausted its worker pool and queue depth grew, causing request latency that led to API timeouts."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "Ingest's worker pool was exhausted (all 16 workers busy) and request queue depth rose to 67.",
      "status": "confirmed",
      "cites": ["ingest-M000c"]
    },
    {
      "claim": "Because workers were saturated, incoming requests waited in the queue for hundreds of milliseconds to over a second, increasing ingest's response latency.",
      "status": "confirmed",
      "cites": ["ingest-S007e0", "ingest-S007ed"]
    },
    {
      "claim": "Api clients calling ingest timed out after ~3 seconds, producing 503/504 errors at the entry service.",
      "status": "confirmed",
      "cites": ["api-S00821", "api-S007b2"]
    }
  ],
  "alternatives": [
    {
      "category": "internal_errors",
      "service": "billing",
      "why_less_likely": "Billing errors and pool exhaustion appear after the API failure burst began, so they are likely an effect rather than the root cause.",
      "cites": ["billing-S003d9", "billing-L00026"]
    },
    {
      "category": "dependency_slow",
      "service": "broker",
